PRAGMA foreign_keys = ON;

CREATE TABLE organizations (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
CREATE TABLE users (id INTEGER PRIMARY KEY, organization_id INTEGER NOT NULL REFERENCES organizations(id), username TEXT NOT NULL, display_name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), UNIQUE(organization_id, username));
CREATE TABLE currencies (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, minor_units INTEGER NOT NULL DEFAULT 2);
CREATE TABLE bank_masters (id INTEGER PRIMARY KEY, organization_id INTEGER NOT NULL REFERENCES organizations(id), code TEXT NOT NULL, name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), UNIQUE(organization_id, code));
CREATE TABLE accounts (id INTEGER PRIMARY KEY, organization_id INTEGER NOT NULL REFERENCES organizations(id), code TEXT, name TEXT NOT NULL, parent_id INTEGER REFERENCES accounts(id), account_type TEXT NOT NULL CHECK(account_type IN ('asset','liability','equity','income','expense')), account_level INTEGER NOT NULL DEFAULT 4 CHECK(account_level BETWEEN 1 AND 4), account_head_type TEXT NOT NULL DEFAULT '', account_note TEXT NOT NULL DEFAULT '', is_control INTEGER NOT NULL DEFAULT 0 CHECK(is_control IN (0,1)), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), UNIQUE(organization_id, code));
CREATE TABLE customers (id INTEGER PRIMARY KEY, organization_id INTEGER NOT NULL REFERENCES organizations(id), account_id INTEGER REFERENCES accounts(id), code TEXT NOT NULL, display_name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), UNIQUE(organization_id, code));
CREATE TABLE stations (id INTEGER PRIMARY KEY, organization_id INTEGER NOT NULL REFERENCES organizations(id), code TEXT NOT NULL, name TEXT NOT NULL, UNIQUE(organization_id, code));
CREATE TABLE cost_center_heads (id INTEGER PRIMARY KEY, organization_id INTEGER NOT NULL REFERENCES organizations(id), code TEXT NOT NULL, name TEXT NOT NULL, UNIQUE(organization_id, code));
CREATE TABLE cost_centers (id INTEGER PRIMARY KEY, organization_id INTEGER NOT NULL REFERENCES organizations(id), code TEXT NOT NULL, name TEXT NOT NULL, head_id INTEGER REFERENCES cost_center_heads(id), UNIQUE(organization_id, code));
CREATE TABLE receipt_headers (id INTEGER PRIMARY KEY, organization_id INTEGER NOT NULL REFERENCES organizations(id), receipt_no TEXT NOT NULL, receipt_date TEXT NOT NULL, currency_id INTEGER NOT NULL REFERENCES currencies(id), currency_type TEXT NOT NULL DEFAULT 'buying' CHECK(currency_type IN ('buying','selling')), exchange_rate NUMERIC NOT NULL CHECK(exchange_rate > 0), call_label TEXT NOT NULL DEFAULT '', cheque_type TEXT NOT NULL DEFAULT '', locker TEXT NOT NULL DEFAULT '', remarks TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending','approved','posted','void')), created_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(organization_id, receipt_no));
CREATE TABLE payment_headers (id INTEGER PRIMARY KEY, organization_id INTEGER NOT NULL REFERENCES organizations(id), payment_no TEXT NOT NULL, payment_date TEXT NOT NULL, currency_id INTEGER NOT NULL REFERENCES currencies(id), exchange_rate NUMERIC NOT NULL CHECK(exchange_rate > 0), remarks TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','posted','void')), created_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(organization_id,payment_no));
CREATE TABLE receipt_lines (id INTEGER PRIMARY KEY, receipt_id INTEGER NOT NULL REFERENCES receipt_headers(id) ON DELETE CASCADE, line_no INTEGER NOT NULL, customer_id INTEGER NOT NULL REFERENCES customers(id), station_id INTEGER REFERENCES stations(id), cost_center_id INTEGER REFERENCES cost_centers(id), employee_label TEXT NOT NULL DEFAULT '', comment TEXT NOT NULL DEFAULT '', invoice_no TEXT NOT NULL DEFAULT '', invoice_rate NUMERIC NOT NULL DEFAULT 1 CHECK(invoice_rate > 0), payment_type TEXT NOT NULL CHECK(payment_type IN ('cash','cheque','bank_transfer','other')), gross_amount NUMERIC NOT NULL CHECK(gross_amount >= 0), gross_secondary NUMERIC NOT NULL DEFAULT 0 CHECK(gross_secondary >= 0), discount_amount NUMERIC NOT NULL DEFAULT 0 CHECK(discount_amount >= 0 AND discount_amount <= gross_amount), discount_secondary NUMERIC NOT NULL DEFAULT 0 CHECK(discount_secondary >= 0), instrument_no TEXT, instrument_date TEXT, UNIQUE(receipt_id, line_no));
CREATE TABLE deposit_splits (id INTEGER PRIMARY KEY, receipt_id INTEGER NOT NULL REFERENCES receipt_headers(id) ON DELETE CASCADE, line_no INTEGER NOT NULL, account_id INTEGER NOT NULL REFERENCES accounts(id), customer_id INTEGER REFERENCES customers(id), method TEXT NOT NULL CHECK(method IN ('cash','cheque','bank_transfer','other')), reference TEXT NOT NULL DEFAULT '', bank_label TEXT NOT NULL DEFAULT '', instrument_no TEXT NOT NULL DEFAULT '', instrument_date TEXT, currency_date TEXT, station_id INTEGER REFERENCES stations(id), cost_center_id INTEGER REFERENCES cost_centers(id), amount NUMERIC NOT NULL CHECK(amount >= 0), amount_secondary NUMERIC NOT NULL DEFAULT 0 CHECK(amount_secondary >= 0), UNIQUE(receipt_id, line_no));
CREATE TABLE payment_lines (id INTEGER PRIMARY KEY, payment_id INTEGER NOT NULL REFERENCES payment_headers(id) ON DELETE CASCADE, line_no INTEGER NOT NULL, account_id INTEGER NOT NULL REFERENCES accounts(id), customer_id INTEGER REFERENCES customers(id), station_id INTEGER REFERENCES stations(id), cost_center_id INTEGER REFERENCES cost_centers(id), employee_label TEXT NOT NULL DEFAULT '', comment TEXT NOT NULL DEFAULT '', invoice_no TEXT NOT NULL DEFAULT '', payment_type TEXT NOT NULL DEFAULT 'other' CHECK(payment_type IN ('cash','cheque','bank_transfer','other')), instrument_no TEXT NOT NULL DEFAULT '', instrument_date TEXT, gross_amount NUMERIC NOT NULL CHECK(gross_amount >= 0), discount_amount NUMERIC NOT NULL DEFAULT 0 CHECK(discount_amount >= 0 AND discount_amount <= gross_amount), UNIQUE(payment_id,line_no));
CREATE TABLE payment_splits (id INTEGER PRIMARY KEY, payment_id INTEGER NOT NULL REFERENCES payment_headers(id) ON DELETE CASCADE, line_no INTEGER NOT NULL, account_id INTEGER NOT NULL REFERENCES accounts(id), method TEXT NOT NULL CHECK(method IN ('cash','cheque','bank_transfer','other')), cheque_book TEXT NOT NULL DEFAULT '', reference TEXT NOT NULL DEFAULT '', instrument_no TEXT NOT NULL DEFAULT '', instrument_date TEXT, station_id INTEGER REFERENCES stations(id), cost_center_id INTEGER REFERENCES cost_centers(id), amount NUMERIC NOT NULL CHECK(amount >= 0), UNIQUE(payment_id,line_no));
CREATE TABLE expense_headers (id INTEGER PRIMARY KEY, organization_id INTEGER NOT NULL REFERENCES organizations(id), expense_no TEXT NOT NULL, expense_date TEXT NOT NULL, reference_no TEXT NOT NULL DEFAULT '', payment_type TEXT NOT NULL CHECK(payment_type IN ('cash','bank')), from_account_id INTEGER NOT NULL REFERENCES accounts(id), instrument_no TEXT NOT NULL DEFAULT '', currency_id INTEGER NOT NULL REFERENCES currencies(id), exchange_rate NUMERIC NOT NULL CHECK(exchange_rate > 0), remarks TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending','approved','rejected','posted','void')), created_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(organization_id,expense_no));
CREATE TABLE expense_lines (id INTEGER PRIMARY KEY, expense_id INTEGER NOT NULL REFERENCES expense_headers(id) ON DELETE CASCADE, line_no INTEGER NOT NULL, account_id INTEGER NOT NULL REFERENCES accounts(id), description TEXT NOT NULL DEFAULT '', reference TEXT NOT NULL DEFAULT '', station_id INTEGER REFERENCES stations(id), cost_center_id INTEGER REFERENCES cost_centers(id), employee_label TEXT NOT NULL DEFAULT '', currency_amount NUMERIC NOT NULL CHECK(currency_amount > 0), base_amount NUMERIC NOT NULL CHECK(base_amount > 0), UNIQUE(expense_id,line_no));
CREATE TABLE cheques (id INTEGER PRIMARY KEY, organization_id INTEGER NOT NULL REFERENCES organizations(id), receipt_id INTEGER NOT NULL REFERENCES receipt_headers(id), deposit_split_id INTEGER REFERENCES deposit_splits(id), replacement_of_id INTEGER REFERENCES cheques(id), cheque_no TEXT NOT NULL, cheque_date TEXT NOT NULL, currency_date TEXT, signatory TEXT NOT NULL DEFAULT '', payer_bank TEXT NOT NULL, customer_id INTEGER NOT NULL REFERENCES customers(id), currency_id INTEGER NOT NULL REFERENCES currencies(id), currency_rate NUMERIC NOT NULL CHECK(currency_rate > 0), amount NUMERIC NOT NULL CHECK(amount > 0), base_amount NUMERIC NOT NULL CHECK(base_amount > 0), status TEXT NOT NULL DEFAULT 'in_hand' CHECK(status IN ('in_hand','deposited','transferred','presented','cleared','bounced','returned')), locker TEXT NOT NULL DEFAULT '', remarks TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(organization_id,payer_bank,cheque_no));
CREATE TABLE cheque_events (id INTEGER PRIMARY KEY, cheque_id INTEGER NOT NULL REFERENCES cheques(id), event_type TEXT NOT NULL CHECK(event_type IN ('received','deposited','presented','cleared','bounced','physical_return','replacement_created','transferred')), from_status TEXT, to_status TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', reference TEXT NOT NULL DEFAULT '', actor_id INTEGER REFERENCES users(id), occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE journal_headers (id INTEGER PRIMARY KEY, organization_id INTEGER NOT NULL REFERENCES organizations(id), voucher_no TEXT NOT NULL, voucher_date TEXT NOT NULL, voucher_type TEXT NOT NULL DEFAULT 'JV', reference_no TEXT NOT NULL DEFAULT '', currency_id INTEGER REFERENCES currencies(id), exchange_rate NUMERIC NOT NULL DEFAULT 1 CHECK(exchange_rate > 0), source_type TEXT NOT NULL, source_id INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','posted','reversed')), created_by INTEGER NOT NULL REFERENCES users(id), posted_at TEXT, UNIQUE(organization_id, voucher_no), UNIQUE(source_type, source_id));
CREATE TABLE journal_lines (id INTEGER PRIMARY KEY, journal_id INTEGER NOT NULL REFERENCES journal_headers(id) ON DELETE CASCADE, line_no INTEGER NOT NULL, account_id INTEGER NOT NULL REFERENCES accounts(id), customer_id INTEGER REFERENCES customers(id), station_id INTEGER REFERENCES stations(id), cost_center_id INTEGER REFERENCES cost_centers(id), employee_label TEXT NOT NULL DEFAULT '', instrument_no TEXT NOT NULL DEFAULT '', instrument_date TEXT, description TEXT NOT NULL DEFAULT '', debit NUMERIC NOT NULL DEFAULT 0 CHECK(debit >= 0), credit NUMERIC NOT NULL DEFAULT 0 CHECK(credit >= 0), currency_debit NUMERIC NOT NULL DEFAULT 0 CHECK(currency_debit >= 0), currency_credit NUMERIC NOT NULL DEFAULT 0 CHECK(currency_credit >= 0), CHECK((debit = 0) <> (credit = 0)), UNIQUE(journal_id, line_no));
CREATE TABLE approval_events (id INTEGER PRIMARY KEY, entity_type TEXT NOT NULL, entity_id INTEGER NOT NULL, action TEXT NOT NULL CHECK(action IN ('submitted','approved','rejected','posted','voided')), actor_id INTEGER NOT NULL REFERENCES users(id), note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_log (id INTEGER PRIMARY KEY, organization_id INTEGER NOT NULL REFERENCES organizations(id), actor_id INTEGER REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id INTEGER, detail TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE INDEX ix_receipts_org_date ON receipt_headers(organization_id, receipt_date);
CREATE INDEX ix_receipt_lines_customer ON receipt_lines(customer_id, receipt_id);
CREATE INDEX ix_journal_source ON journal_headers(source_type, source_id);
CREATE INDEX ix_journal_lines_account ON journal_lines(account_id, journal_id);
CREATE INDEX ix_cheques_org_status_date ON cheques(organization_id,status,cheque_date);
CREATE INDEX ix_cheque_events_cheque_date ON cheque_events(cheque_id,occurred_at);

-- Posting must be transactional and reject unbalanced journals in the service layer.
-- Net receipt = sum(gross - discount); deposit split total must equal receipt net.

-- Customer statements include only posted journal lines tagged to a customer.
CREATE VIEW v_customer_statement_lines AS
SELECT jl.customer_id,cu.display_name AS customer_name,jh.voucher_date AS entry_date,
       jh.voucher_no AS document_no,jh.source_type,jl.description,jl.debit,jl.credit,
       SUM(jl.debit-jl.credit) OVER (
         PARTITION BY jl.customer_id ORDER BY jh.voucher_date,jh.id,jl.line_no
         ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
       ) AS running_balance
FROM journal_lines jl
JOIN journal_headers jh ON jh.id=jl.journal_id AND jh.status='posted'
JOIN customers cu ON cu.id=jl.customer_id
WHERE jl.customer_id IS NOT NULL;
